}

import { redirect } from "next/navigation"

export default function InsightsPage() {
  redirect("/dashboard/insights/earnings")
}

import type { Metadata, Viewport } from "next"
import { Inter } from "next/font/google"
import { cookies } from "next/headers"

import { SIDEBAR_COOKIE } from "@/lib/natasha/constants"
import { Toaster } from "@/components/ui/sonner"
import { TooltipProvider } from "@/components/ui/tooltip"
import { AppShell } from "@/components/natasha/app-shell"

const inter = Inter({ subsets: ["latin"], axes: ["opsz"], display: "swap" })

export const metadata: Metadata = {
  title: { default: "Dashboard", template: "%s · Natasha" },
}

export const viewport: Viewport = {
  themeColor: "#141414",
  colorScheme: "dark",
}

/**
 * Everything the dashboard needs lives here (font, tooltips, toasts), so the
 * template drops into any Next.js app without touching the root layout.
 */
export default async function DashboardLayout({ children }: { children: React.ReactNode }) {
  const stored = (await cookies()).get(SIDEBAR_COOKIE)?.value
  const defaultCollapsed = stored === undefined ? undefined : stored === "collapsed"

  return (
    <>
      {/* Feeds Inter into the theme's --font-sans, portalled popovers included. */}
      <style>{`:root{--font-inter:${inter.style.fontFamily}}`}</style>
      <TooltipProvider delayDuration={200}>
        <AppShell defaultCollapsed={defaultCollapsed}>{children}</AppShell>
      </TooltipProvider>
      <Toaster position="bottom-right" />
    </>
  )
}

import type { Metadata } from "next"

import { Page } from "@/components/natasha/page"
import { PageHeader } from "@/components/natasha/page-header"
import { ProductForm } from "@/components/natasha/product-form"

export const metadata: Metadata = { title: "New product" }

export default function NewProductPage() {
  return (
    <Page>
      <PageHeader title="New product" />
      <ProductForm />
    </Page>
  )
}

import type { Metadata } from "next"

import { products } from "@/lib/natasha/data"
import { Page } from "@/components/natasha/page"
import { PageHeader } from "@/components/natasha/page-header"
import { ProductCatalog } from "@/components/natasha/product-catalog"

export const metadata: Metadata = { title: "Products" }

export default async function ProductsPage({ searchParams }: { searchParams: Promise<{ q?: string }> }) {
  const { q } = await searchParams
  const query = q?.trim().toLowerCase()
  const list = query
    ? products.filter((p) => p.name.toLowerCase().includes(query) || p.category.toLowerCase().includes(query))
    : products

  return (
    <Page>
      <PageHeader title="Products" />
      {/* Remount on a new search so pagination resets. */}
      <ProductCatalog key={query ?? ""} products={list} />
    </Page>
  )
}

import type { Metadata } from "next"

import { getProduct, sales } from "@/lib/natasha/data"
import { Card } from "@/components/ui/card"
import { Page } from "@/components/natasha/page"
import { PageHeader } from "@/components/natasha/page-header"
import { RangeToolbar } from "@/components/natasha/range-toolbar"
import { SalesTable, type SaleRow } from "@/components/natasha/sales-table"

export const metadata: Metadata = { title: "Sales" }

export default async function SalesPage({ searchParams }: { searchParams: Promise<{ q?: string }> }) {
  const { q } = await searchParams
  const query = q?.trim().toLowerCase()
  const rows: SaleRow[] = sales
    .map((sale) => {
      const { id, name, sku, art, image } = getProduct(sale.productId)!
      return { ...sale, product: { id, name, sku, art, image } }
    })
    .filter((row) => !query || row.product.name.toLowerCase().includes(query) || String(row.id).includes(query))

  return (
    <Page>
      <PageHeader title="Sales" searchHref="/dashboard/sales" />
      <RangeToolbar />
      <Card className="gap-0 py-0">
        <SalesTable key={query ?? ""} rows={rows} />
      </Card>
    </Page>
  )
}

