"use client"

import * as React from "react"
import { usePathname } from "next/navigation"

import { Sheet, SheetContent, SheetDescription, SheetTitle } from "@/components/ui/sheet"
import { SIDEBAR_COOKIE } from "@/lib/natasha/constants"
import { AppSidebar, SidebarBody } from "@/components/natasha/app-sidebar"
import { ShellContext } from "@/components/natasha/shell-context"

const NARROW_QUERY = "(max-width: 1439px)"

function subscribeNarrow(onChange: () => void) {
  const query = window.matchMedia(NARROW_QUERY)
  query.addEventListener("change", onChange)
  return () => query.removeEventListener("change", onChange)
}

function isNarrow() {
  return window.matchMedia(NARROW_QUERY).matches
}

/**
 * Dashboard frame: sticky sidebar (336px ↔ 104px) + scrolling content.
 * The collapsed state persists in a cookie so the server renders it without a
 * flash, and ⌘B / Ctrl+B toggles it from anywhere.
 */
export function AppShell({
  defaultCollapsed,
  children,
}: {
  /** From the cookie. `undefined` means "first visit" → collapse on narrow screens. */
  defaultCollapsed?: boolean
  children: React.ReactNode
}) {
  // Until the user picks a state, the sidebar follows the viewport width.
  const [preference, setPreference] = React.useState(defaultCollapsed)
  const narrow = React.useSyncExternalStore(subscribeNarrow, isNarrow, () => false)
  const collapsed = preference ?? narrow
  const [mobileOpen, setMobileOpen] = React.useState(false)
  const pathname = usePathname()

  const setCollapsed = React.useCallback((value: boolean) => {
    setPreference(value)
    document.cookie = `${SIDEBAR_COOKIE}=${value ? "collapsed" : "expanded"}; path=/; max-age=31536000; samesite=lax`
  }, [])

  const toggleCollapsed = React.useCallback(() => setCollapsed(!collapsed), [collapsed, setCollapsed])

  // Close the mobile drawer after navigating.
  const [lastPathname, setLastPathname] = React.useState(pathname)
  if (pathname !== lastPathname) {
    setLastPathname(pathname)
    setMobileOpen(false)
  }

  React.useEffect(() => {
    function onKeyDown(event: KeyboardEvent) {
      if (event.key.toLowerCase() === "b" && (event.metaKey || event.ctrlKey)) {
        event.preventDefault()
        toggleCollapsed()
      }
    }
    window.addEventListener("keydown", onKeyDown)
    return () => window.removeEventListener("keydown", onKeyDown)
  }, [toggleCollapsed])

  const value = React.useMemo(
    () => ({ collapsed, setCollapsed, toggleCollapsed, mobileOpen, setMobileOpen }),
    [collapsed, setCollapsed, toggleCollapsed, mobileOpen]
  )

  return (
    <ShellContext.Provider value={value}>
      <div data-collapsed={collapsed} className="group/shell flex min-h-dvh bg-background">
        <AppSidebar />
        <Sheet open={mobileOpen} onOpenChange={setMobileOpen}>
          <SheetContent
            side="left"
            showCloseButton={false}
            className="w-84 max-w-[calc(100vw-48px)] gap-0 border-r border-border bg-sidebar p-0 sm:max-w-84"
          >
            <SheetTitle className="sr-only">Navigation</SheetTitle>
            <SheetDescription className="sr-only">Main navigation for the Natasha dashboard</SheetDescription>
            <SidebarBody variant="mobile" />
          </SheetContent>
        </Sheet>
        <div className="flex min-w-0 flex-1 flex-col">{children}</div>
      </div>
    </ShellContext.Provider>
  )
}

"use client"

import * as React from "react"
import Link from "next/link"
import { usePathname } from "next/navigation"
import {
  Banknote,
  BadgeCheck,
  ChartPie,
  ChevronDown,
  CircleHelp,
  House,
  Inbox,
  Megaphone,
  PanelLeftClose,
  PanelLeftOpen,
  Puzzle,
  Settings,
  ShoppingBag,
  Tag,
  type LucideIcon,
} from "lucide-react"

import { cn } from "@/lib/utils"
import { unreadCount } from "@/lib/natasha/data"
import { Button } from "@/components/ui/button"
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { useShell } from "@/components/natasha/shell-context"
import { Logo, LogoMark } from "@/components/natasha/logo"

type NavLeaf = { title: string; href: string }
type NavItem = {
  title: string
  icon: LucideIcon
  href: string
  badge?: number
  items?: NavLeaf[]
}
type NavSection = { label: string; items: NavItem[] }

export const navigation: NavSection[] = [
  {
    label: "Store",
    items: [
      { title: "Dashboard", icon: House, href: "/dashboard" },
      { title: "Sales", icon: Tag, href: "/dashboard/sales" },
      { title: "Products", icon: ShoppingBag, href: "/dashboard/products" },
      {
        title: "Insights",
        icon: ChartPie,
        href: "/dashboard/insights",
        items: [
          { title: "Earnings", href: "/dashboard/insights/earnings" },
          { title: "Traffic sources", href: "/dashboard/insights/traffic" },
          { title: "Conversions", href: "/dashboard/insights/conversions" },
        ],
      },
      { title: "Marketing", icon: Megaphone, href: "/dashboard/marketing" },
      { title: "Payouts", icon: Banknote, href: "/dashboard/payouts" },
    ],
  },
  {
    label: "Support",
    items: [
      { title: "Inbox", icon: Inbox, href: "/dashboard/inbox", badge: unreadCount },
      { title: "Help center", icon: CircleHelp, href: "/dashboard/help" },
    ],
  },
  {
    label: "System",
    items: [
      { title: "Extensions", icon: Puzzle, href: "/dashboard/extensions" },
      { title: "Settings", icon: Settings, href: "/dashboard/settings" },
      { title: "Go premium", icon: BadgeCheck, href: "/dashboard/premium" },
    ],
  },
]

function isActive(pathname: string, href: string) {
  if (href === "/dashboard") return pathname === "/dashboard"
  return pathname === href || pathname.startsWith(`${href}/`)
}

/* Shared item styles ------------------------------------------------------- */

const itemBase =
  "relative flex items-center rounded-lg border border-transparent type-body-lg text-foreground outline-none transition-[background-color,border-color,color] hover:bg-secondary focus-visible:ring-3 focus-visible:ring-ring/40"
const itemActive =
  "border-primary-border bg-primary text-primary-foreground shadow-[inset_0_1px_0_rgb(255_255_255/0.16)] hover:bg-primary"
/** Expanded vs. icon-only geometry. */
const itemLayout = (collapsed: boolean) =>
  collapsed ? "mx-auto h-12 w-14 justify-center" : "h-12 w-full gap-4 px-4"

/* Sidebar ------------------------------------------------------------------ */

export function AppSidebar() {
  return (
    <aside
      data-slot="sidebar"
      className="sticky top-0 hidden h-dvh w-84 shrink-0 flex-col overflow-hidden border-r border-border bg-sidebar transition-[width] duration-300 ease-[cubic-bezier(.2,.8,.2,1)] group-data-[collapsed=true]/shell:w-26 lg:flex"
    >
      <SidebarBody variant="desktop" />
    </aside>
  )
}

export function SidebarBody({ variant }: { variant: "desktop" | "mobile" }) {
  const { collapsed: collapsedState, toggleCollapsed } = useShell()
  const collapsed = variant === "desktop" && collapsedState
  const pathname = usePathname()

  return (
    <div className="flex h-full min-h-0 flex-col">
      <div className="shrink-0 px-4">
        <div
          className={cn(
            "flex h-23 items-center border-b border-border",
            collapsed ? "justify-center" : "justify-between pr-1 pl-4"
          )}
        >
          {collapsed ? (
            <Tooltip>
              <TooltipTrigger asChild>
                <button
                  type="button"
                  onClick={toggleCollapsed}
                  aria-label="Expand sidebar"
                  className="group/logo relative grid size-12 place-items-center rounded-lg outline-none hover:bg-secondary focus-visible:ring-3 focus-visible:ring-ring/40"
                >
                  <LogoMark className="transition-opacity group-hover/logo:opacity-0 group-focus-visible/logo:opacity-0" />
                  <PanelLeftOpen className="absolute size-5 opacity-0 transition-opacity group-hover/logo:opacity-100 group-focus-visible/logo:opacity-100" />
                </button>
              </TooltipTrigger>
              <TooltipContent side="right">
                Expand <kbd className="ml-1 text-muted-foreground">⌘B</kbd>
              </TooltipContent>
            </Tooltip>
          ) : (
            <>
              <Link href="/dashboard" className="rounded-lg outline-none focus-visible:ring-3 focus-visible:ring-ring/40">
                <Logo />
              </Link>
              {variant === "desktop" && (
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Button variant="ghost" size="icon" onClick={toggleCollapsed} aria-label="Collapse sidebar" className="text-muted-foreground hover:text-foreground">
                      <PanelLeftClose />
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent side="right">
                    Collapse <kbd className="ml-1 text-muted-foreground">⌘B</kbd>
                  </TooltipContent>
                </Tooltip>
              )}
            </>
          )}
        </div>
      </div>

      <nav aria-label="Main" className="no-scrollbar min-h-0 flex-1 overflow-y-auto px-4">
        {navigation.map((section) => (
          <div key={section.label} className="border-b border-border py-6 last:border-b-0">
            {!collapsed && (
              <p className="mb-5 px-4 type-overline text-muted-foreground">{section.label}</p>
            )}
            <ul className="flex flex-col gap-1">
              {section.items.map((item) => (
                <li key={item.title}>
                  {item.items ? (
                    <NavGroup item={item} pathname={pathname} collapsed={collapsed} />
                  ) : (
                    <NavLink item={item} active={isActive(pathname, item.href)} collapsed={collapsed} />
                  )}
                </li>
              ))}
            </ul>
          </div>
        ))}
      </nav>
    </div>
  )
}

function NavLink({ item, active, collapsed }: { item: NavItem; active: boolean; collapsed: boolean }) {
  const Icon = item.icon
  const link = (
    <Link
      href={item.href}
      aria-current={active ? "page" : undefined}
      className={cn(itemBase, itemLayout(collapsed), active && itemActive)}
    >
      <Icon className="size-5 shrink-0" strokeWidth={2} />
      {!collapsed && <span className="min-w-0 flex-1 truncate">{item.title}</span>}
      {item.badge ? (
        <span
          className={cn(
            "grid place-items-center rounded-full border tabular-nums",
            collapsed
              ? "absolute -top-0.5 right-1 size-5 border-primary-border bg-primary text-[11px] leading-none font-semibold text-primary-foreground ring-2 ring-sidebar"
              : "h-6 min-w-8 px-2 type-caption",
            !collapsed && (active ? "border-white/70 bg-transparent" : "border-primary-border bg-primary text-primary-foreground")
          )}
        >
          {item.badge}
          <span className="sr-only"> unread</span>
        </span>
      ) : null}
    </Link>
  )

  if (!collapsed) return link
  return (
    <Tooltip>
      <TooltipTrigger asChild>{link}</TooltipTrigger>
      <TooltipContent side="right">{item.title}</TooltipContent>
    </Tooltip>
  )
}

function NavGroup({ item, pathname, collapsed }: { item: NavItem; pathname: string; collapsed: boolean }) {
  const childActive = item.items?.some((child) => isActive(pathname, child.href)) ?? false
  const [open, setOpen] = React.useState(childActive)
  const Icon = item.icon

  // Expand the group when navigation lands on one of its children.
  const [wasChildActive, setWasChildActive] = React.useState(childActive)
  if (childActive !== wasChildActive) {
    setWasChildActive(childActive)
    if (childActive) setOpen(true)
  }

  if (collapsed) {
    return (
      <DropdownMenu>
        <Tooltip>
          <TooltipTrigger asChild>
            <DropdownMenuTrigger
              aria-label={item.title}
              className={cn(itemBase, itemLayout(true), childActive && itemActive)}
            >
              <Icon className="size-5 shrink-0" strokeWidth={2} />
            </DropdownMenuTrigger>
          </TooltipTrigger>
          <TooltipContent side="right">{item.title}</TooltipContent>
        </Tooltip>
        <DropdownMenuContent side="right" align="start" sideOffset={12} className="w-52">
          <DropdownMenuLabel className="px-3 py-2 type-overline text-muted-foreground">{item.title}</DropdownMenuLabel>
          {item.items?.map((child) => (
            <DropdownMenuItem key={child.href} asChild>
              <Link
                href={child.href}
                className={cn("type-body-lg", isActive(pathname, child.href) && "text-primary-light")}
              >
                {child.title}
              </Link>
            </DropdownMenuItem>
          ))}
        </DropdownMenuContent>
      </DropdownMenu>
    )
  }

  return (
    <Collapsible open={open} onOpenChange={setOpen}>
      <CollapsibleTrigger className={cn(itemBase, itemLayout(false))}>
        <Icon className="size-5 shrink-0" strokeWidth={2} />
        <span className="min-w-0 flex-1 truncate text-left">{item.title}</span>
        <ChevronDown
          className={cn("size-5 text-muted-foreground transition-transform duration-200", open && "rotate-180")}
        />
      </CollapsibleTrigger>
      <CollapsibleContent className="overflow-hidden data-[state=closed]:animate-collapsible-up data-[state=open]:animate-collapsible-down">
        <ul className="mt-1 mr-6 ml-7 flex flex-col gap-1 border-l border-border pl-2">
          {item.items?.map((child) => {
            const active = isActive(pathname, child.href)
            return (
              <li key={child.href}>
                <Link
                  href={child.href}
                  aria-current={active ? "page" : undefined}
                  className={cn(itemBase, "h-10 px-4", active && itemActive)}
                >
                  {child.title}
                </Link>
              </li>
            )
          })}
        </ul>
      </CollapsibleContent>
    </Collapsible>
  )
}

"use client"

import { Bar, BarChart, CartesianGrid, Cell, XAxis, YAxis } from "recharts"

import { cn } from "@/lib/utils"
import {
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
  type ChartConfig,
} from "@/components/ui/chart"
import {
  axisLine,
  axisTick,
  BrandGradient,
  gridStroke,
  percentTicks,
  SlantedTick,
  useChartId,
} from "@/components/natasha/charts/primitives"

type Datum = Record<string, string | number>

/* Grouped bars ------------------------------------------------------------- */

export function GroupedBarChart({
  data,
  xKey,
  series,
  barSize = 24,
  barGap = 8,
  className,
}: {
  data: Datum[]
  xKey: string
  series: { key: string; label: string; color: string }[]
  barSize?: number
  barGap?: number
  className?: string
}) {
  const config = Object.fromEntries(
    series.map((s) => [s.key, { label: s.label, color: s.color }])
  ) satisfies ChartConfig

  return (
    <ChartContainer config={config} className={cn("aspect-auto h-56 w-full", className)}>
      <BarChart data={data} barGap={barGap} margin={{ top: 8, right: 0, bottom: 0, left: 0 }} accessibilityLayer>
        <CartesianGrid vertical={false} stroke={gridStroke} />
        <YAxis
          domain={[0, 100]}
          ticks={percentTicks}
          tick={axisTick}
          tickLine={false}
          axisLine={axisLine}
          width={32}
          tickMargin={8}
        />
        <XAxis dataKey={xKey} tick={<SlantedTick />} tickLine={false} axisLine={axisLine} interval={0} height={40} />
        <ChartTooltip cursor={{ fill: "var(--secondary)", opacity: 0.6 }} content={<ChartTooltipContent />} />
        {series.map((s) => (
          <Bar key={s.key} dataKey={s.key} fill={`var(--color-${s.key})`} radius={[4, 4, 0, 0]} barSize={barSize} />
        ))}
      </BarChart>
    </ChartContainer>
  )
}

/* Single-series gradient bars --------------------------------------------- */

export function GradientBarChart({
  data,
  xKey,
  yKey,
  label = "Value",
  barSize = 56,
  radius = 2,
  showYAxis = true,
  className,
  valuePrefix = "",
  valueSuffix = "",
}: {
  data: Datum[]
  xKey: string
  yKey: string
  label?: string
  barSize?: number
  radius?: number
  showYAxis?: boolean
  className?: string
  valuePrefix?: string
  valueSuffix?: string
}) {
  const id = useChartId("bar")
  const config = { [yKey]: { label, color: "var(--chart-2)" } } satisfies ChartConfig

  return (
    <ChartContainer config={config} className={cn("aspect-auto h-56 w-full", className)}>
      <BarChart data={data} margin={{ top: 8, right: 0, bottom: 0, left: 0 }} accessibilityLayer>
        <defs>
          <BrandGradient id={id} />
        </defs>
        <CartesianGrid vertical={false} stroke={gridStroke} />
        <YAxis
          hide={!showYAxis}
          domain={[0, 100]}
          ticks={percentTicks}
          tick={axisTick}
          tickLine={false}
          axisLine={axisLine}
          width={32}
          tickMargin={8}
        />
        <XAxis dataKey={xKey} tick={<SlantedTick />} tickLine={false} axisLine={axisLine} interval={0} height={40} />
        <ChartTooltip
          cursor={{ fill: "var(--secondary)", opacity: 0.6 }}
          content={
            <ChartTooltipContent
              hideIndicator
              formatter={(value) => (
                <span className="flex w-full justify-between gap-4">
                  <span className="text-muted-foreground">{label}</span>
                  <span className="tabular-nums text-foreground">
                    {valuePrefix}
                    {Number(value).toLocaleString()}
                    {valueSuffix}
                  </span>
                </span>
              )}
            />
          }
        />
        <Bar dataKey={yKey} fill={`url(#${id})`} radius={[radius, radius, 0, 0]} barSize={barSize} />
      </BarChart>
    </ChartContainer>
  )
}

/* Horizontal bars ---------------------------------------------------------- */

export function HorizontalBarChart({
  data,
  categoryKey,
  valueKey,
  label = "Visits",
  ticks = [0, 50, 100, 150, 200, 250, 300, 350],
  className,
}: {
  data: (Datum & { fill: string })[]
  categoryKey: string
  valueKey: string
  label?: string
  ticks?: number[]
  className?: string
}) {
  const config = { [valueKey]: { label, color: "var(--chart-2)" } } satisfies ChartConfig
  return (
    <ChartContainer config={config} className={cn("aspect-auto h-64 w-full", className)}>
      <BarChart data={data} layout="vertical" margin={{ top: 0, right: 8, bottom: 0, left: 0 }} accessibilityLayer>
        <CartesianGrid horizontal={false} stroke={gridStroke} />
        <XAxis
          type="number"
          domain={[0, ticks[ticks.length - 1]]}
          ticks={ticks}
          tick={<SlantedTick />}
          tickLine={false}
          axisLine={false}
          height={40}
          interval={0}
        />
        <YAxis
          type="category"
          dataKey={categoryKey}
          tickLine={false}
          axisLine={axisLine}
          width={124}
          tickMargin={12}
          tick={{ fill: "var(--muted-foreground)", fontSize: 14, fontWeight: 500 }}
        />
        <ChartTooltip cursor={{ fill: "var(--secondary)", opacity: 0.5 }} content={<ChartTooltipContent hideIndicator />} />
        <Bar dataKey={valueKey} radius={6} barSize={28}>
          {data.map((entry) => (
            <Cell key={String(entry[categoryKey])} fill={entry.fill} />
          ))}
        </Bar>
      </BarChart>
    </ChartContainer>
  )
}

"use client"

import { cn } from "@/lib/utils"
