/* Geometry helpers --------------------------------------------------------- */

/** Rounded to 0.01 so server and browser trig agree (no hydration drift). */
function polar(cx: number, cy: number, r: number, deg: number) {
  const rad = (deg * Math.PI) / 180
  const round = (n: number) => Math.round(n * 100) / 100
  return [round(cx + r * Math.sin(rad)), round(cy - r * Math.cos(rad))] as const
}

function arc(cx: number, cy: number, r: number, from: number, to: number) {
  const [x0, y0] = polar(cx, cy, r, from)
  const [x1, y1] = polar(cx, cy, r, to)
  const large = to - from > 180 ? 1 : 0
  return `M${x0.toFixed(2)} ${y0.toFixed(2)}A${r} ${r} 0 ${large} 1 ${x1.toFixed(2)} ${y1.toFixed(2)}`
}

/* Gauge -------------------------------------------------------------------- */

export function Gauge({
  value,
  max = 100,
  className,
  children,
  footer,
}: {
  /** 0–max */
  value: number
  max?: number
  className?: string
  /** Rendered in the middle of the arc. */
  children?: React.ReactNode
  /** Rendered at the bottom, between the 0 and max labels. */
  footer?: React.ReactNode
}) {
  const id = useChartId("gauge")
  const sweep = 240
  const start = -sweep / 2
  const ratio = Math.min(Math.max(value / max, 0), 1)
  const [lx, ly] = polar(100, 100, 82, start)
  const [rx, ry] = polar(100, 100, 82, start + sweep)

  return (
    <div className={cn("relative mx-auto aspect-[200/176] w-full max-w-56", className)}>
      <svg viewBox="0 0 200 176" className="size-full overflow-visible" role="img" aria-label={`${Math.round(ratio * 100)}% of target`}>
        <defs>
          <linearGradient id={id} x1="0" y1="1" x2="1" y2="0">
            <stop offset="0%" stopColor="var(--chart-4)" />
            <stop offset="55%" stopColor="var(--chart-3)" />
            <stop offset="100%" stopColor="var(--chart-1)" />
          </linearGradient>
        </defs>
        <path d={arc(100, 100, 82, start, start + sweep)} fill="none" stroke="var(--track)" strokeWidth={20} strokeLinecap="round" />
        <path
          d={arc(100, 100, 82, start, start + sweep * ratio)}
          fill="none"
          stroke={`url(#${id})`}
          strokeWidth={20}
          strokeLinecap="round"
        />
        <text x={lx} y={ly + 30} textAnchor="middle" fill="var(--muted-foreground)" fontSize={10} fontWeight={600}>
          0
        </text>
        <text x={rx} y={ry + 30} textAnchor="middle" fill="var(--muted-foreground)" fontSize={10} fontWeight={600}>
          {formatCompact(max)}
        </text>
      </svg>
      <div className="absolute inset-x-0 top-[40%] flex -translate-y-1/2 justify-center">{children}</div>
      {footer && <div className="absolute inset-x-0 bottom-0 flex justify-center">{footer}</div>}
    </div>
  )
}

/* Concentric progress rings ----------------------------------------------- */

export function RadialRings({
  data,
  className,
}: {
  data: { name: string; value: number; color: string }[]
  className?: string
}) {
  const size = 240
  const c = size / 2
  const stroke = 8
  const gap = 12
  return (
    <svg viewBox={`0 0 ${size} ${size}`} className={cn("aspect-square w-full max-w-60", className)} role="img" aria-label="Traffic sources">
      {[...data].reverse().map((d, i) => {
        const r = c - stroke / 2 - i * (stroke + gap)
        const circumference = 2 * Math.PI * r
        return (
          <g key={d.name}>
            <title>{`${d.name}: ${d.value}%`}</title>
            <circle cx={c} cy={c} r={r} fill="none" stroke="var(--accent)" strokeWidth={stroke} />
            <circle
              cx={c}
              cy={c}
              r={r}
              fill="none"
              stroke={d.color}
              strokeWidth={stroke}
              strokeLinecap="round"
              strokeDasharray={`${(d.value / 100) * circumference} ${circumference}`}
              transform={`rotate(-90 ${c} ${c})`}
            />
          </g>
        )
      })}
    </svg>
  )
}

/* Ring progress (ratings) ------------------------------------------------- */

export function RingProgress({ value, max = 5, className }: { value: number; max?: number; className?: string }) {
  const r = 19
  const circumference = 2 * Math.PI * r
  return (
    <svg viewBox="0 0 48 48" className={cn("size-12 shrink-0", className)} aria-hidden>
      <circle cx="24" cy="24" r={r} fill="none" stroke="var(--accent)" strokeWidth={4} />
      <circle
        cx="24"
        cy="24"
        r={r}
        fill="none"
        stroke="var(--primary)"
        strokeWidth={4}
        strokeLinecap="round"
        strokeDasharray={`${(value / max) * circumference} ${circumference}`}
        transform="rotate(-90 24 24)"
      />
    </svg>
  )
}

/* Radar (hexagon) ---------------------------------------------------------- */

export function CategoryRadar({
  data,
  className,
}: {
  data: { category: string; value: number }[]
  className?: string
}) {
  const id = useChartId("radar")
  const cx = 200
  const cy = 156
  const R = 112
  const n = data.length
  const vertex = (i: number, r: number) => polar(cx, cy, r, (360 / n) * i)
  const outline = data.map((_, i) => vertex(i, R).join(",")).join(" ")
  const shape = data.map((d, i) => vertex(i, (d.value / 100) * (R - 10)).join(",")).join(" ")

  return (
    <svg viewBox="0 0 400 312" className={cn("w-full", className)} role="img" aria-label="Top categories">
      <defs>
        <linearGradient id={id} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor="var(--gradient-from)" />
          <stop offset="100%" stopColor="var(--gradient-to)" />
        </linearGradient>
        <filter id={`${id}-glow`} x="-30%" y="-30%" width="160%" height="160%">
          <feGaussianBlur stdDeviation="14" />
        </filter>
      </defs>
      <polygon points={outline} fill="none" stroke="var(--input)" strokeWidth={1.5} />
      <polygon points={shape} fill={`url(#${id})`} opacity={0.35} filter={`url(#${id}-glow)`} />
      <polygon points={shape} fill={`url(#${id})`} stroke="var(--primary-light)" strokeOpacity={0.4} />
      {data.map((d, i) => {
        const [x, y] = vertex(i, R)
        const [lx, ly] = vertex(i, R + 22)
        const angle = (360 / n) * i
        const anchor = angle === 0 || angle === 180 ? "middle" : angle < 180 ? "start" : "end"
        const offsetX = anchor === "start" ? 6 : anchor === "end" ? -6 : 0
        return (
          <g key={d.category}>
            <title>{`${d.category}: ${d.value}`}</title>
            <circle cx={x} cy={y} r={5} fill="var(--subtle-foreground)" />
            <text
              x={lx + offsetX}
              y={ly + (angle === 0 ? -4 : angle === 180 ? 8 : 4)}
              textAnchor={anchor}
              dominantBaseline="middle"
              fill="var(--foreground)"
              fontSize={14}
              fontWeight={500}
            >
              {d.category}
            </text>
          </g>
        )
      })}
    </svg>
  )
}

"use client"

import { Area, AreaChart, CartesianGrid, Line, LineChart, XAxis, YAxis } from "recharts"

import { cn } from "@/lib/utils"
import {
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
  type ChartConfig,
} from "@/components/ui/chart"
import {
  axisLine,
  axisTick,
  BrandGradient,
  FadeGradient,
  gridStroke,
  percentTicks,
  PillDot,
  SlantedTick,
  useChartId,
} from "@/components/natasha/charts/primitives"

type TrendDatum = { value: number; label?: string } & Record<string, string | number | undefined>

/**
 * Line / area trend with a pinned value pill. Hover moves the pill; on idle it
 * rests on `pillIndex`.
 */
export function TrendChart({
  data,
  xKey = "x",
  tickKey,
  variant = "line",
  curve = "monotone",
  fill = "fade",
  grid = "vertical",
  showXAxis = false,
  pillIndex,
  label = "Value",
  className,
}: {
  data: TrendDatum[]
  /** Must be unique per point (the tooltip resolves points by it). */
  xKey?: string
  /** Optional field shown as the x tick label; blank values hide the tick. */
  tickKey?: string
  variant?: "line" | "area"
  curve?: "monotone" | "linear"
  fill?: "fade" | "brand"
  grid?: "vertical" | "horizontal"
  showXAxis?: boolean
  /** Point the pill rests on when nothing is hovered. Each datum's `label` is shown. */
  pillIndex?: number
  label?: string
  className?: string
}) {
  const id = useChartId("trend")
  const config = { value: { label, color: "var(--chart-5)" } } satisfies ChartConfig
  const pill = (props: { cx?: number; cy?: number; payload?: TrendDatum }) => (
    <PillDot
      cx={props.cx}
      cy={props.cy}
      label={props.payload ? (props.payload.label ?? String(props.payload.value)) : ""}
    />
  )

  const axes = (
    <>
      <CartesianGrid vertical={grid === "vertical"} horizontal={grid === "horizontal"} stroke={gridStroke} />
      <YAxis domain={[0, 100]} ticks={percentTicks} tick={axisTick} tickLine={false} axisLine={axisLine} width={32} tickMargin={8} />
      <XAxis
        dataKey={xKey}
        hide={!showXAxis}
        tick={<SlantedTick />}
        tickFormatter={tickKey ? (_, index) => String(data[index]?.[tickKey] ?? "") : undefined}
        tickLine={false}
        axisLine={axisLine}
        interval={0}
        height={showXAxis ? 40 : 0}
      />
      <ChartTooltip cursor={false} defaultIndex={pillIndex} content={() => null} />
    </>
  )

  return (
    <ChartContainer
      config={config}
      className={cn("aspect-auto h-32 w-full [&_.recharts-surface]:overflow-visible", className)}
    >
      {variant === "line" ? (
        <LineChart data={data} margin={{ top: 8, right: 8, bottom: 0, left: 0 }}>
          {axes}
          <Line
            dataKey="value"
            type={curve}
            stroke="var(--color-value)"
            strokeWidth={3}
            dot={false}
            activeDot={pill}
            strokeLinecap="round"
          />
        </LineChart>
      ) : (
        <AreaChart data={data} margin={{ top: 8, right: 8, bottom: 0, left: 0 }}>
          <defs>
            {fill === "brand" ? <BrandGradient id={id} /> : <FadeGradient id={id} />}
          </defs>
          {axes}
          <Area
            dataKey="value"
            type={curve}
            stroke={fill === "brand" ? "none" : "var(--color-value)"}
            strokeWidth={3}
            fill={`url(#${id})`}
            fillOpacity={1}
            dot={false}
            activeDot={pill}
          />
        </AreaChart>
      )}
    </ChartContainer>
  )
}

/* Overlapping areas (lead sources) ---------------------------------------- */

export function LayeredAreaChart({
  data,
  xKey,
  series,
  className,
}: {
  data: Record<string, string | number>[]
  xKey: string
  series: { key: string; label: string; color: string; opacity?: number }[]
  className?: string
}) {
  const config = Object.fromEntries(series.map((s) => [s.key, { label: s.label, color: s.color }])) satisfies ChartConfig
  return (
    <ChartContainer config={config} className={cn("aspect-auto h-64 w-full", className)}>
      <AreaChart data={data} margin={{ top: 8, right: 0, bottom: 0, left: 0 }}>
        <CartesianGrid vertical={false} stroke={gridStroke} />
        <YAxis domain={[0, 100]} ticks={percentTicks} tick={axisTick} tickLine={false} axisLine={axisLine} width={32} tickMargin={8} />
        <XAxis dataKey={xKey} tick={<SlantedTick />} tickLine={false} axisLine={axisLine} interval={0} height={40} />
        <ChartTooltip cursor={{ stroke: "var(--border)" }} content={<ChartTooltipContent />} />
        {series.map((s) => (
          <Area
            key={s.key}
            dataKey={s.key}
            type="linear"
            stroke="none"
            fill={`var(--color-${s.key})`}
            fillOpacity={s.opacity ?? 0.7}
            activeDot={{ r: 4, fill: s.color, stroke: "var(--card)", strokeWidth: 2 }}
          />
        ))}
      </AreaChart>
    </ChartContainer>
  )
}

/* Sparkline (pure SVG, no tooltip) ---------------------------------------- */

function smoothPath(points: [number, number][]) {
  if (points.length < 2) return ""
  let d = `M${points[0][0]},${points[0][1]}`
  for (let i = 0; i < points.length - 1; i++) {
    const [x0, y0] = points[Math.max(0, i - 1)]
    const [x1, y1] = points[i]
    const [x2, y2] = points[i + 1]
    const [x3, y3] = points[Math.min(points.length - 1, i + 2)]
    const c1x = x1 + (x2 - x0) / 6
    const c1y = y1 + (y2 - y0) / 6
    const c2x = x2 - (x3 - x1) / 6
    const c2y = y2 - (y3 - y1) / 6
    d += ` C${c1x.toFixed(2)},${c1y.toFixed(2)} ${c2x.toFixed(2)},${c2y.toFixed(2)} ${x2},${y2}`
  }
  return d
}

export function Sparkline({
  values,
  className,
  width = 144,
  height = 40,
}: {
  values: number[]
  className?: string
  width?: number
  height?: number
}) {
  const id = useChartId("spark")
  const min = Math.min(...values)
  const max = Math.max(...values)
  const points = values.map((v, i): [number, number] => [
    Math.round((i / (values.length - 1)) * width * 100) / 100,
    Math.round((height - 4 - ((v - min) / (max - min || 1)) * (height - 8)) * 100) / 100,
  ])
  const line = smoothPath(points)
  return (
    <svg viewBox={`0 0 ${width} ${height}`} className={cn("h-10 w-36 overflow-visible", className)} aria-hidden>
      <defs>
        <FadeGradient id={id} opacity={0.3} />
      </defs>
      <path d={`${line} L${width},${height} L0,${height} Z`} fill={`url(#${id})`} />
      <path d={line} fill="none" stroke="var(--chart-5)" strokeWidth={2} strokeLinecap="round" />
    </svg>
  )
}

